class User {
  constructor(name, age) {
    this.name = name;
    this.age = age;
  }

  greet() {
    return `Hi, I'm ${this.name}, age ${this.age}`;
  }
}

let alex = new User("Alex", 25);
console.log(alex.greet());  // "Hi, I'm Alex, age 25"
console.log(alex instanceof User);  // true

class Temperature {
  constructor(celsius) {
    this.celsius = celsius;
  }

  // Computed property
  get fahrenheit() {
    return this.celsius * 9/5 + 32;
  }

  // Validated setter
  set celsius(value) {
    if (value < -273.15) throw new Error("Below absolute zero!");
    this._celsius = value;
  }

  get celsius() {
    return this._celsius;
  }

  // Static utility
  static fromFahrenheit(f) {
    return new Temperature((f - 32) * 5/9);
  }
}

let temp = new Temperature(100);
console.log(temp.fahrenheit);  // 212 (getter)

let cold = Temperature.fromFahrenheit(32);
console.log(cold.celsius);  // 0 (static method)

class BankAccount {
  #balance = 0;
  #pin;

  constructor(owner, pin, initial = 0) {
    this.owner = owner;
    this.#pin = pin;
    this.#balance = initial;
  }

  withdraw(amount, pin) {
    if (pin !== this.#pin) throw new Error("Wrong PIN!");
    if (amount > this.#balance) throw new Error("Insufficient funds!");
    this.#balance -= amount;
    return this.#balance;
  }

  get balance() {
    return this.#balance;
  }
}

let account = new BankAccount("Alex", "1234", 1000);
console.log(account.balance);  // 1000
account.withdraw(200, "1234");
console.log(account.balance);  // 800
// account.#balance  → SyntaxError!

class Animal {
  constructor(name) {
    this.name = name;
  }

  speak() {
    return `${this.name} makes a noise`;
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);  // must call before using 'this'
    this.breed = breed;
  }

  // Override parent method
  speak() {
    return `${this.name} barks!`;
  }

  // Add new method
  fetch(item) {
    return `${this.name} fetches the ${item}`;
  }
}

let rex = new Dog("Rex", "German Shepherd");
console.log(rex.speak());      // "Rex barks!"
console.log(rex.fetch("ball")); // "Rex fetches the ball"
